/* Lesson data: A* search on a grid (structure mode). Steps are generated by simulating the search. */
(function () {
  var COLS = 6, ROWS = 4;
  var walls = { '2,0': 1, '2,1': 1, '4,3': 1 };
  var S = [0, 2], G = [5, 2];
  function id(c, r) { return 'g' + c + r; }
  function px(c) { return 120 + c * 125; }
  function gy(r) { return 45 + r * 55; }
  function manh(c, r) { return Math.abs(c - G[0]) + Math.abs(r - G[1]); }

  function simulate(useH) {
    var ops = [];
    for (var r = 0; r < ROWS; r++) for (var c = 0; c < COLS; c++) {
      var lbl = (c === S[0] && r === S[1]) ? 'S' : (c === G[0] && r === G[1]) ? 'G' : (walls[c + ',' + r] ? '#' : '');
      ops.push(['node', id(c, r), lbl, px(c), gy(r), 'cell']);
      if (walls[c + ',' + r]) ops.push(['tag', id(c, r), 'dim']);
    }
    var steps = [{ pl: 0, cl: 0, h: 380, say: useH ? 'A* on a grid. Each move costs 1. Walls (#) block. A* always expands the open cell with the smallest f = g + h, where g is the cost so far and h is a guess of the cost left (Manhattan distance to G).' : 'Same grid, but with h = 0 for every cell. That removes the guess, so f = g and this is exactly Dijkstra: it expands outward in all directions.', csay: 'open = [(h(start), 0, start)]', ds: ops }];
    var g = {}, closed = {}, open = [], order = 0, expanded = 0;
    g[S[0] + ',' + S[1]] = 0;
    function h(c, r) { return useH ? manh(c, r) : 0; }
    open.push({ f: h(S[0], S[1]), h: h(S[0], S[1]), o: order++, c: S[0], r: S[1], cost: 0 });
    steps.push({ pl: 0, cl: 0, h: 380, say: 'Put S in the open set with f = ' + h(S[0], S[1]) + '. Cells in the open set are marked; expanded (closed) cells turn solid.', csay: 'Push start.', ds: [['tag', id(S[0], S[1]), 'mark']] });
    var prev = null, found = false;
    while (open.length) {
      open.sort(function (a, b) { return a.f - b.f || a.h - b.h || a.o - b.o; });
      var cur = open.shift(), key = cur.c + ',' + cur.r;
      if (closed[key]) continue;
      var o = [];
      if (prev) o.push(['untag', prev, 'cur']);
      o.push(['untag', id(cur.c, cur.r), 'mark'], ['tag', id(cur.c, cur.r), 'cur']);
      expanded++;
      if (cur.c === G[0] && cur.r === G[1]) {
        steps.push({ pl: 3, cl: 3, h: 380, say: 'Pop G with cost ' + cur.cost + ': the shortest path has ' + cur.cost + ' moves. The search expanded ' + expanded + ' cells' + (useH ? ' (compare with the h = 0 scene, which expands more).' : ' (A* with a good h expands fewer).'), csay: 'return cost;', ds: o });
        found = true; break;
      }
      steps.push({ pl: 2, cl: 2, h: 380, say: 'Expand the open cell with the smallest f = ' + cur.f + ' (g = ' + cur.cost + ', h = ' + cur.h + ') at column ' + cur.c + ', row ' + cur.r + '.', csay: 'Pop the minimum f.', ds: o });
      closed[key] = 1; prev = id(cur.c, cur.r);
      var steps2 = [];
      [[1, 0], [-1, 0], [0, 1], [0, -1]].forEach(function (d) {
        var nc = cur.c + d[0], nr = cur.r + d[1], nk = nc + ',' + nr;
        if (nc < 0 || nr < 0 || nc >= COLS || nr >= ROWS || walls[nk] || closed[nk]) return;
        var ng = cur.cost + 1;
        if (g[nk] === undefined || ng < g[nk]) {
          g[nk] = ng;
          var hv = h(nc, nr);
          open.push({ f: ng + hv, h: hv, o: order++, c: nc, r: nr, cost: ng });
          steps2.push(['lab', id(nc, nr), String(ng + hv)], ['tag', id(nc, nr), 'mark']);
        }
      });
      if (steps2.length) steps.push({ pl: 4, cl: 4, h: 380, say: 'Look at the neighbours: each new or improved cell gets f = g + h written in it and joins the open set.', csay: 'Push neighbours.', ds: steps2 });
    }
    if (!found) steps.push({ pl: 7, cl: 7, h: 380, say: 'The open set is empty: no path.', csay: 'return -1;', ds: [] });
    return steps;
  }

  var py = ['open = [(h(start), 0, start)]; g = {start: 0}', 'while open:', '    f, cost, cur = heappop(open)          # smallest f = g + h', '    if cur == goal: return cost', '    for nb in neighbours(cur):', '        if cost + 1 < g.get(nb, INF):', '            g[nb] = cost + 1', '            heappush(open, (cost + 1 + h(nb), cost + 1, nb))', 'return None'];
  var c = ['heap_push(&open, start, h(start), 0); g[start] = 0;', 'while (!heap_empty(&open)) {', '    node cur = heap_pop(&open);            /* smallest f = g + h */', '    if (cur.id == goal) return cur.g;', '    for (each neighbour nb of cur.id) {', '        if (cur.g + 1 < g[nb]) {', '            g[nb] = cur.g + 1;', '            heap_push(&open, nb, cur.g + 1 + h(nb), cur.g + 1);', '    }}} return -1;'];
  var trap = 'The heuristic must never overestimate (be admissible), and for a plain closed-set version it should also be consistent. An overestimating h can return a longer path than the true shortest. h = 0 is always safe: it is Dijkstra.';

  window.LESSON = {
    id: 'a-star',
    mode: 'ds',
    title: 'A* search',
    lede:
      'A* is Dijkstra with a compass. Dijkstra expands cells by cost so far (g). A* expands by g + h, where h is an optimistic guess of the cost still to go. If h never overestimates, the first time the goal is popped its path is the shortest, and good guesses mean far fewer cells are explored. Used in maps, games and robot planning.',
    scenes: [
      { id: 'astar', title: 'A* with Manhattan h', blurb: 'The search heads towards G and ignores most of the grid.', trap: trap, pyCode: py, cCode: c, predict: { q: 'On a grid with 4-direction moves of cost 1, which h is admissible?', options: ['Manhattan distance to the goal', 'Twice the Manhattan distance', 'The number of walls left'], answer: 0, why: 'You need at least as many moves as the Manhattan distance, so it never overestimates. Doubling it can overestimate and break optimality.' }, steps: simulate(true) },
      { id: 'dijkstra', title: 'Same grid with h = 0 (Dijkstra)', blurb: 'Without a guess the search spreads in every direction before reaching G.', trap: trap, pyCode: py, cCode: c, predict: { q: 'With h = 0 for every cell, A* behaves like which algorithm?', options: ['Depth-first search', 'Dijkstra', 'Greedy best-first'], answer: 1, why: 'f = g, so cells are expanded in order of cost so far, which is Dijkstra.' }, steps: simulate(false) },
    ],
    builtins: [
      ['heapq.heappush / heappop', 'The priority queue for the open set; push tuples (f, tiebreaker, node).'],
      ['abs(dx) + abs(dy)', 'Manhattan distance heuristic for 4-direction grids.'],
      ['max(abs(dx), abs(dy))', 'Chebyshev distance: use when diagonal moves cost 1.'],
      ['g.get(nb, INF)', 'Best known cost so far, defaulting to infinity.'],
      ['math.hypot(dx, dy)', 'Euclidean distance, the usual heuristic for free movement.'],
    ],
  };
})();
